#define circle(p,s) (length(p)-s)
#define PI acos(-1.)
#define hash21(x) fract(sin(dot(x,vec2(164.5, 231.8)))*2164.5)
#define dt(s,o) fract((iTime+o)*s)

// iq's distance function
// https://iquilezles.org/articles/distfunctions/
float opExtrusion (vec3 p, float d, float h)
{
    vec2 w = vec2( d, abs(p.z) - h );
    return min(max(w.x,w.y),0.0) + length(max(w,0.0));
}

float truchet (vec2 uv, float w)
{
    vec2 id = floor(uv);

    uv = fract(uv)-.5;
    if(hash21(id)<.5) uv.x *= -1.;
    float s = (uv.x>-uv.y)?1.:-1.;
    uv -= .5*s;

    float contour = abs(circle(uv,.5))-w;
    return contour;
}

float SDF (vec3 p)
{
    p.z += iTime;
    float per = 1.5;
    float id = floor(p.z/per);
    p.z = mod(p.z,per)-per*.5;
    vec2 pp = p.xy+id*.5;
    float width = sin(length(p.xy)-dt(.3, -id*.2)*(2.*PI))*.1;
    return opExtrusion(p, truchet(pp, width), .05 );
}


void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = (2.*fragCoord-iResolution.xy)/iResolution.y;

    float dither = hash21(uv);

    vec3 ro = vec3(0.001,0.01,-2.), rd=normalize(vec3(uv,1.)), p=ro,
    col=vec3(0.);
    float shad; bool hit = false;
    for(float i=0.; i<64.;i++)
    {
        float d = SDF(p);
        if (d<0.01)
        {
            hit = true;
            shad = i/64.;
            break;
        }
        d *= .45+0.01*dither;
        p += d*rd;
    }
    if(hit)
    {
        col = vec3(1.-shad); 
    }

    // Output to screen
    fragColor = vec4(col,1.0);
}
